command:
if (!game.user.isGM) return ui.notifications.warn('Repair Items (World) is GM-only.');

const proceed = await foundry.applications.api.DialogV2.confirm({
  window: { title: 'Repair Items (World)' },
  classes: ['emblem-rpg', 'dialog-editor'],
  content: `
    <div class="ed-container">
      <div class="ed-section">
        <p class="ed-description">Return every item carried by every unit in the world to its full uses?</p>
      </div>
    </div>`,
  rejectClose: false
});
if (!proceed) return;

const result = await game.emblemRpg.api.development.repairItems({ scope: 'world' });

console.group(`emblem-rpg | Repair Items (World) — ${result.ok ? 'settled' : 'refused'}`);
console.log(result.ok ? result.data : result);
console.groupEnd();
